```typescript
      // Strip ACP-only fields silently when spawning a subagent (schema-following
      // models may include them in the tool call even when runtime="subagent").
      const streamToSubagent = streamTo && runtime === "acp" ? streamTo : undefined;
      const resumeSessionIdSubagent = resumeSessionId && runtime === "acp" ? resumeSessionId : undefined;
```

